"""Figures are generated by functions also called in the executed notebook."""
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import networkx as nx
import numpy as np
from .data import ROOT
from .experiment import load, VARIABLES, STRENGTHS
from .model import predict, field, propagation_graph

LABELS = (r'$n$',r'$a$ [Np/m]',r'$b$ [Np/m]')
COLORS = ('#2563eb','#e97316','#16a085')


def save(fig,name):
    fig.tight_layout()
    fig.savefig(ROOT/'figures'/f'{name}.png',dpi=160,bbox_inches='tight')
    return fig


def observations(name,report,arr):
    f=arr[name+'_f'];y=arr[name+'_y'];mask=arr[name+'_mask'];ex=arr[name+'_intervention_example']
    p=predict(f,report['datasets'][name]['parameters'])
    fig,ax=plt.subplots(1,2,figsize=(11,3.8))
    for j,label in enumerate((r'Attenuation $\alpha$ [Np/m]',r'Phase constant $\beta$ [rad/m]')):
        ax[j].plot(f*1e-9,y[:,j],'.',ms=3,label='Observed')
        ax[j].plot(f*1e-9,p[:,j],color=COLORS[1],label='Maxwell TEM fit')
        ax[j].plot(f[~mask]*1e-9,y[~mask,j],'o',ms=4,mfc='none',label='Held-out bands')
        ax[j].set(xlabel='Frequency [GHz]',ylabel=label,title=name)
    ax[0].legend(fontsize=8)
    return save(fig,name+'_fit')


def intervention(name,report,arr):
    f=arr[name+'_f'];y=arr[name+'_y'];p=predict(f,report['datasets'][name]['parameters'])
    ex=arr[name+'_intervention_example']
    fig,ax=plt.subplots(1,2,figsize=(11,3.6))
    for j,label in enumerate((r'$\alpha$',r'$\beta$')):
        ax[j].plot(f*1e-9,(y-p)[:,j],label='Original residual')
        ax[j].plot(f*1e-9,(ex-p)[:,j],alpha=.7,label=r'After intervention $\lambda=2$')
        ax[j].set(xlabel='Frequency [GHz]',ylabel=label+' residual [1/m]')
    ax[0].legend(fontsize=8)
    return save(fig,name+'_intervention')


def distributions(name,loss,arr):
    base=arr[f'{name}_{loss}_baseline'];samples=arr[f'{name}_{loss}_samples']
    fig,ax=plt.subplots(1,3,figsize=(12,3.4))
    for j in range(3):
        for l,color in zip((0,2,4),COLORS):
            values=base[:,j] if l==0 else samples[2,l,:,j]
            ax[j].hist(values,bins=28,density=True,histtype='step',lw=1.5,color=color,label=rf'$\lambda={STRENGTHS[l]:g}$')
        ax[j].set(xlabel=LABELS[j],ylabel='Density',title=f'{name}, {loss}')
    ax[0].legend(fontsize=8)
    return save(fig,f'{name}_{loss}_distributions')


def distance_plot(name,arr):
    fig,ax=plt.subplots(1,3,figsize=(12,3.5))
    for j in range(3):
        for v,label in enumerate(VARIABLES):
            for loss,ls in (('linear','-'),('soft_l1','--')):
                val=arr[f'{name}_{loss}_W1_SD'][v,:,j]
                ax[j].plot(STRENGTHS,val,ls,marker='o',ms=3,color=COLORS[v],label=f'{label}, {loss}')
        ax[j].set(xlabel=r'Intervention strength $\lambda$',ylabel=r'$W_1$/baseline SD',title=LABELS[j])
        ax[j].grid(alpha=.2)
    ax[0].legend(fontsize=6.5)
    return save(fig,name+'_distance')


def joint_plot(name,arr):
    base=arr[f'{name}_linear_baseline'];changed=arr[f'{name}_linear_samples'][2,4]
    fig,ax=plt.subplots(1,2,figsize=(10,3.7))
    ax[0].scatter(base[:,1],base[:,2],s=7,alpha=.35,label='Original')
    ax[0].scatter(changed[:,1],changed[:,2],s=7,alpha=.25,label=r'$\lambda=4$')
    ax[0].set(xlabel=LABELS[1],ylabel=LABELS[2],title='Joint distribution; compensation')
    ax[0].legend(fontsize=8)
    for v,label in enumerate(VARIABLES):ax[1].plot(STRENGTHS,arr[f'{name}_linear_SW1'][v],'-o',color=COLORS[v],label=label)
    ax[1].set(xlabel=r'$\lambda$',ylabel='Standardized sliced W1',title='128 fixed projections')
    ax[1].legend(fontsize=8)
    return save(fig,name+'_joint')


def ablation_plot(report):
    fig,ax=plt.subplots(1,2,figsize=(10,3.7))
    for i,name in enumerate(('synthetic','measured')):
        rows=report['datasets'][name]['ablation']
        cost=np.array([r['holdout_reduced']-r['holdout_full'] for r in rows])
        upper=np.array([r['delta_upper95'] for r in rows])
        ax[i].bar(np.arange(3),np.maximum(cost,1e-4),color=[COLORS[2] if r['decision']=='remove' else COLORS[0] for r in rows])
        ax[i].scatter(np.arange(3),np.maximum(upper,1e-4),marker='_',color='black',label='Bootstrap upper 95%')
        ax[i].axhline(.25,color=COLORS[1],ls='--',label='Equivalence tolerance')
        ax[i].set(xticks=range(3),xticklabels=['n=1','a=0','b=0'],yscale='log',
                  ylabel='Increase in standardized holdout RMS',title=name)
    ax[0].legend(fontsize=7)
    return save(fig,'ablation')


def graph_plot():
    g=propagation_graph();net=g.networkx()
    pos={0:(4,3),1:(1,3),2:(-2,3),3:(0,3),4:(-3,3),5:(3,3),
         6:(.5,2),7:(-2.5,2),8:(-1,1),9:(3.5,2),10:(2,1)}
    labels={i:(node.name or node.kind) for i,node in enumerate(g.nodes)}
    labels[3]='sqrt(f/f0)';labels[4]='f/f0';labels[5]='omega/c'
    labels[8]='alpha: +';labels[10]='beta: +'
    fig,ax=plt.subplots(figsize=(11,4))
    colors=['#ffe0b3' if d.kind=='parameter' else '#d8eaf9' if d.kind=='field' else '#d9edd9' for d in g.nodes]
    nx.draw_networkx(net,pos,labels=labels,node_color=colors,node_shape='s',node_size=2400,font_size=8,ax=ax,arrowsize=16)
    ax.set_axis_off();ax.margins(.16)
    return save(fig,'propagation_graph')


def wave_plot(report):
    x=np.linspace(0,.20,301);t=np.linspace(0,4e-10,241)
    fig,ax=plt.subplots(1,2,figsize=(10,3.8))
    for j,name in enumerate(('synthetic','measured')):
        e,_=field(x,t,1e10,report['datasets'][name]['parameters'])
        im=ax[j].pcolormesh(x*100,t*1e9,e,cmap='RdBu_r',shading='auto',vmin=-1,vmax=1)
        ax[j].set(xlabel='Distance [cm]',ylabel='Time [ns]',title=f'{name}: modeled E, 10 GHz')
    fig.colorbar(im,ax=ax.ravel().tolist(),label='Normalized electric field',pad=.03)
    fig.subplots_adjust(wspace=.28,right=.84)
    fig.savefig(ROOT/'figures'/'wave.png',dpi=160,bbox_inches='tight')
    return fig


def make_all():
    report,arr=load()
    figs=[graph_plot(),wave_plot(report),ablation_plot(report)]
    for name in ('synthetic','measured'):
        figs.extend((observations(name,report,arr),intervention(name,report,arr),
                     distance_plot(name,arr),joint_plot(name,arr)))
        for loss in ('linear','soft_l1'):figs.append(distributions(name,loss,arr))
    for fig in figs:plt.close(fig)
    return len(figs)


def presentation_figures():
    """Larger labels and one diagnostic per slide; full figures stay in notebook."""
    report,arr=load()
    with plt.rc_context({'font.size':13,'axes.titlesize':14,'legend.fontsize':10}):
        f=arr['measured_f'];y=arr['measured_y'];mask=arr['measured_mask']
        pred=predict(f,report['datasets']['measured']['parameters'])
        fig,ax=plt.subplots(figsize=(7.2,3.8))
        ax.plot(f*1e-9,y[:,0],'.',label='Observed')
        ax.plot(f*1e-9,pred[:,0],color=COLORS[1],label='Model')
        ax.plot(f[~mask]*1e-9,y[~mask,0],'o',mfc='none',label='Held-out bands')
        ax.set(xlabel='Frequency [GHz]',ylabel=r'$\alpha$ [Np/m]')
        ax.legend();save(fig,'slide_fit');plt.close(fig)
        fig,ax=plt.subplots(figsize=(7.2,3.8))
        base=arr['measured_linear_baseline'];samples=arr['measured_linear_samples']
        for l,color in zip((0,2,4),COLORS):
            val=base[:,2] if l==0 else samples[2,l,:,2]
            ax.hist(val,bins=28,density=True,histtype='step',lw=1.8,color=color,label=rf'$\lambda={STRENGTHS[l]:g}$')
        ax.axvline(0,color='black',lw=1,ls=':',label='Null b=0')
        ax.set(xlabel=r'$b$ [Np/m]',ylabel='Density',title='Measured data: additional loss coefficient')
        ax.legend();save(fig,'slide_distribution');plt.close(fig)
        fig,ax=plt.subplots(figsize=(7.2,3.8))
        for v,label in enumerate(VARIABLES):
            for loss,ls in (('linear','-'),('soft_l1','--')):
                ax.plot(STRENGTHS,arr[f'measured_{loss}_W1_SD'][v,:,2],ls,marker='o',ms=3,
                        color=COLORS[v],label=f'{label}, {loss}')
        ax.set(xlabel=r'Intervention strength $\lambda$',ylabel=r'$W_1(b)/SD_0(b)$')
        ax.grid(alpha=.2);ax.legend(ncol=2);save(fig,'slide_distance');plt.close(fig)
